def reciprocal_rank(ranked, relevant):
    for i, doc in enumerate(ranked, start=1):
        if doc in relevant:
            return 1 / i
    return 0.0

runs = [(["d4", "d1", "d9"], {"d1"}),
        (["d2", "d7", "d3"], {"d8"}),
        (["d5", "d6", "d0"], {"d5", "d0"})]
print(round(sum(reciprocal_rank(r, rel) for r, rel in runs) / len(runs), 3))

def index_recall(approx_ids, exact_ids, k):
    hits = 0
    for i in range(k):
        if approx_ids[i] == exact_ids[i]:
            hits += 1
    return hits / k
